package com.tarmedtar.screendoodle;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.view.Gravity;import android.widget.*;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(28,36,28,28);l.setGravity(Gravity.CENTER_HORIZONTAL);TextView t=new TextView(this);t.setText("شخبط على الشاشة");t.setTextSize(26);l.addView(t);TextView d=new TextView(this);d.setText("ارسم فوق التطبيقات بقلم وألوان وممحاة. وضع الرسم يلتقط اللمسات؛ اختر تفاعل للعودة لاستخدام التطبيق أسفل الطبقة.");d.setTextSize(16);d.setPadding(0,24,0,24);l.addView(d);Button p=new Button(this);p.setText("منح إذن الظهور فوق التطبيقات");p.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));});l.addView(p);Button s=new Button(this);s.setText("تشغيل الشخبطة");s.setOnClickListener(v->{if(Settings.canDrawOverlays(this)){startService(new Intent(this,DrawingOverlayService.class));finish();}else p.performClick();});l.addView(s);setContentView(l);}}